  const base=framework(root);
  const run=spawnSync(process.execPath,[join(base,'scripts/build-tokens.mjs')],{cwd:base,stdio:'inherit'});
  if(run.status!==0) throw Error('Token generation failed');
  const native=spawnSync(process.execPath,[join(base,'scripts/build-native.mjs')],{cwd:base,stdio:'inherit'});
  if(native.status!==0) throw Error('Native generation failed');
  const markdown=spawnSync(process.execPath,[join(base,'packages/markdown/scripts/embed-envelope-schema.mjs')],{cwd:base,stdio:'inherit'});
